const assert = require('node:assert/strict');

        const { Ledger } = require('../.build/ledger');
        const { PaymentService } = require('../.build/service');
        const { Transient } = require('../.build/transport');

        // Transport whose acknowledge fails with fail(callNumber) when that returns an error.
        function scriptedTransport(fail = () => undefined) {
          const calls = [];
          return {
            calls,
            acknowledge: async receipt => {
              calls.push(receipt);
              const error = fail(calls.length);
              if (error) throw error;
            },
          };
        }
        const isError = message => e => e instanceof Error && !(e instanceof Transient) && e.message === message;

        async function main() {
          const ledger = new Ledger(); const receipts = [];
          const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
          assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
          assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
          await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);

          // Ledger: equal amount returns the original receipt, also under concurrency.
          {
            const l = new Ledger();
            const [a, b, c] = await Promise.all([l.apply('t', 'k', 50), l.apply('t', 'k', 50), l.apply('t', 'k', 50)]);
            assert.equal(l.entries.length, 1);
            assert.strictEqual(a, b); assert.strictEqual(b, c);
            // Different amount under the same tenant/key: conflict, no debit.
            await assert.rejects(l.apply('t', 'k', 51), isError('key conflict'));
            assert.equal(l.entries.length, 1);
            // Same key under another tenant is a separate debit.
            assert.equal((await l.apply('u', 'k', 51)).id, 2);
            assert.equal(l.entries.length, 2);
          }

          // Service: Transient after the debit retries acknowledgement with the same receipt; one debit.
          {
            const l = new Ledger();
            const t = scriptedTransport(n => (n < 3 ? new Transient('busy') : undefined));
            const receipt = await new PaymentService(l, t).pay('shop', 'r1', 500);
            assert.equal(l.entries.length, 1);
            assert.equal(t.calls.length, 3);
            for (const c of t.calls) assert.strictEqual(c, receipt);
          }

          // Service: exhausted retries reject with the final Transient, after exactly `attempts` tries.
          {
            const l = new Ledger(); const errors = [];
            const t = scriptedTransport(n => { const e = new Transient('busy ' + n); errors.push(e); return e; });
            await assert.rejects(new PaymentService(l, t).pay('shop', 'r2', 500, 4), e => e === errors[3]);
            assert.equal(t.calls.length, 4); assert.equal(l.entries.length, 1);
          }

          // Service: attempts=1 means a single try.
          {
            const l = new Ledger(); const t = scriptedTransport(() => new Transient('busy'));
            await assert.rejects(new PaymentService(l, t).pay('shop', 'r2b', 500, 1), Transient);
            assert.equal(t.calls.length, 1); assert.equal(l.entries.length, 1);
          }

          // Service: non-Transient acknowledgement errors are not retried.
          {
            const l = new Ledger(); const boom = new Error('boom');
            const t = scriptedTransport(() => boom);
            await assert.rejects(new PaymentService(l, t).pay('shop', 'r3', 500, 5), e => e === boom);
            assert.equal(t.calls.length, 1); assert.equal(l.entries.length, 1);
          }

          // Service: concurrent pays with the same key debit once and share the receipt.
          {
            const l = new Ledger(); const t = scriptedTransport();
            const svc = new PaymentService(l, t);
            const [r1, r2] = await Promise.all([svc.pay('shop', 'c', 70), svc.pay('shop', 'c', 70)]);
            assert.equal(l.entries.length, 1); assert.strictEqual(r1, r2);
          }

          // Service: reusing a key with another amount throws key conflict, no second debit or ack.
          {
            const l = new Ledger(); const t = scriptedTransport();
            const svc = new PaymentService(l, t);
            await svc.pay('shop', 'x', 10);
            await assert.rejects(svc.pay('shop', 'x', 11), isError('key conflict'));
            assert.equal(l.entries.length, 1); assert.equal(t.calls.length, 1);
          }

          // Validation happens before any ledger or transport action.
          {
            const l = new Ledger(); let applies = 0;
            const realApply = l.apply.bind(l);
            l.apply = async (...args) => { applies++; return realApply(...args); };
            const t = scriptedTransport();
            const svc = new PaymentService(l, t);
            const bad = [
              ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], ['t', undefined, 1],
              ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN],
              ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 2.5], ['t', 'k', 1, '3'], ['t', 'k', 1, NaN],
            ];
            for (const args of bad) await assert.rejects(svc.pay(...args), isError('invalid payment'), JSON.stringify(args));
            assert.equal(applies, 0); assert.equal(t.calls.length, 0); assert.equal(l.entries.length, 0);
            // Boundary values are accepted.
            await svc.pay('t', 'lo', 1, 1); await svc.pay('t', 'hi', 1, 5);
            assert.equal(l.entries.length, 2);
          }
        }
        module.exports = main();
EOF
